 if(arguments.contains("style")){const auto& style=arguments.at("style");if(multiple&&style.is_object()&&style.size()==1&&style.contains("border")){const auto validated=normalizedStyle(style);Json operations=Json::array();for(const auto& range:borderRanges(model,view))for(int row=range.top();row<=range.bottom();++row)for(int col=range.left();col<=range.right();++col)operations.push_back({{"type","set_style"},{"sheet",model.sheetId().toStdString()},{"row",row+1},{"col",col+1},{"style",validated}});operations=worksheetBorderPatchOperations(model,operations);return operations.empty()||model.apply(operations);}return applyStyle(model,view,selectedRange(model,view),style);}
