 for(const auto* side:{"top","bottom","left","right"}){const std::string name(side);const int row=name=="top"?range.top():name=="bottom"?range.bottom():std::clamp(current.row(),range.top(),range.bottom()),col=name=="left"?range.left():name=="right"?range.right():std::clamp(current.column(),range.left(),range.right());int nr=row,nc=col;const char* opposite=nullptr;if(name=="top"){--nr;opposite="bottom";}else if(name=="bottom"){++nr;opposite="top";}else if(name=="left"){--nc;opposite="right";}else{++nc;opposite="left";}const auto own=displayedEdge(row,col,name);const auto other=nr>=0&&nr<model.rowCount()&&nc>=0&&nc<model.columnCount()?displayedEdge(nr,nc,opposite):Json();const auto edge=name=="top"||name=="left"?effectiveWorksheetBorderEdge(own,other):effectiveWorksheetBorderEdge(other,own);if(edge.is_null())displayedBorder.erase(name);else displayedBorder[name]=edge;}initial["border"]=std::move(displayedBorder);
